    var u=Math.min(s.w*0.8/20,s.h*0.3), cxm=s.l+s.w/2-(p.eye==='R'?1:-1)*p.sep*u/2, dxm=cxm+(p.eye==='R'?1:-1)*p.sep*u, cym=s.t+s.h*0.5, v=vis(p);
